231	import java.util.List;
232	import net.officefloor.hq.app.Audit;
233	import net.officefloor.hq.app.sheet.SheetService;
234	import org.springframework.dao.DataIntegrityViolationException;
235	import org.springframework.http.HttpStatus;
236	import org.springframework.orm.ObjectOptimisticLockingFailureException;
237	import org.springframework.stereotype.Service;
238	import org.springframework.transaction.annotation.Transactional;
239	import org.springframework.web.server.ResponseStatusException;
240	
241	/** The people kept on a sheet. */
242	@Service
243	public class PersonService {
244	
245	    private final PersonRepository people;
246	    private final SheetService sheets;
247	    private final Audit audit;
248	
249	    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
250	        this.people = people;
251	        this.sheets = sheets;
252	        this.audit = audit;
253	    }
254	
255	    @Transactional(readOnly = true)
256	    public List<Person> list(String sheetId) {
257	        return people.findBySheetIdOrderByIdAsc(sheetId);
258	    }
259	
260	    @Transactional
261	    public Person add(String by, String sheetId, String name, String grade) {
262	        sheets.load(sheetId);
263	        String trimmed = name.strip();
264	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
265	            throw nameInUse();
266	        }
267	        Person added = save(new Person(sheetId, trimmed, grade));
268	        audit.recordOnCommit(record("PERSON_ADDED", by, added));
269	        return added;
270	    }
271	
272	    /** Saves an edit made from the given version of the person; refused when it has been saved since. */
273	    @Transactional
274	    public Person update(String by, String sheetId, Long id, long version, String name, String grade) {
275	        Person person = people.findByIdAndSheetId(id, sheetId)
276	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
277	        if (person.getVersion() != version) {
278	            throw stale();
279	        }
280	        String trimmed = name.strip();
281	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)) {
282	            throw nameInUse();
283	        }
284	        person.setName(trimmed);
285	        person.setGrade(grade);
286	        Person saved = save(person);
287	        audit.recordOnCommit(record("PERSON_EDITED", by, saved));
288	        return saved;
289	    }
290	
291	    /** Saves the person; the store's unique index refuses a name another request took meanwhile. */
292	    private Person save(Person person) {
293	        try {
294	            return people.saveAndFlush(person);
295	        } catch (DataIntegrityViolationException e) {
296	            throw nameInUse();
297	        } catch (ObjectOptimisticLockingFailureException e) {
298	            // another request saved the person between this one reading and writing it
299	            throw stale();
300	        }
301	    }
302	
303	    private static String record(String event, String by, Person p) {
304	        return event + " sheet=" + p.getSheetId() + " by=" + by + " name=" + p.getName() + " grade=" + p.getGrade();
305	    }
306	
307	    private static ResponseStatusException stale() {
308	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
309	                "Someone else has saved this person since it was opened.");
310	    }
311	
312	    private static ResponseStatusException nameInUse() {
313	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
314	    }
315	}
