346	    public List<Rate> list(String sheetId) {
347	        return rates.findBySheetIdOrderByGradeAscFromAsc(sheetId);
348	    }
349	
350	    /** Sets the grade's rate from the date (null: from the beginning of time), replacing any rate it had for it. */
351	    @Transactional
352	    public Rate set(String by, String sheetId, String grade, LocalDate from, BigDecimal pct) {
353	        sheets.load(sheetId);
354	        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
355	        Rate rate = rates.findExact(sheetId, grade, from).orElseGet(() -> new Rate(sheetId, grade, from, scaled));
356	        rate.setPct(scaled);
357	        Rate saved;
358	        try {
359	            saved = rates.saveAndFlush(rate);
360	        } catch (DataIntegrityViolationException e) {
361	            // another user set this grade's rate for this from-date at the same moment
362	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That rate was just set by someone else.");
363	        }
364	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + by + " grade=" + grade
365	                + " rate=" + saved.getPct().toPlainString() + (from != null ? " from=" + from : ""));
366	        return saved;
367	    }
368	}
