375	
376	/** Loads a sheet by id; a sheet never loaded before starts empty. */
377	@Service
378	public class SheetService {
379	
380	    private final SheetRepository sheets;
381	
382	    public SheetService(SheetRepository sheets) {
383	        this.sheets = sheets;
384	    }
385	
386	    public Sheet load(String id) {
387	        return sheets.findById(id).orElseGet(() -> create(id));
388	    }
389	
390	    /** Change the sheet's today; every date decision on the sheet follows it. */
391	    @Transactional
392	    public Sheet setToday(String id, LocalDate today) {
393	        Sheet sheet = load(id);
394	        sheet.setToday(today);
395	        return sheets.saveAndFlush(sheet);
396	    }
397	
398	    /** Takes the sheet's next claim number; two callers at once never get the same one. */
399	    @Transactional
400	    public long nextClaimNumber(String id) {
401	        load(id);
402	        sheets.incrementClaimNumber(id);
403	        return sheets.lastClaimNumber(id);
404	    }
405	
406	    private Sheet create(String id) {
407	        try {
408	            return sheets.saveAndFlush(new Sheet(id));
409	        } catch (DataIntegrityViolationException e) {
410	            // another user created it at the same moment
411	            return sheets.findById(id).orElseThrow(() -> e);
412	        }
413	    }
414	}
