433	import org.springframework.web.server.ResponseStatusException;
434	
435	/** The statements taken for the people on a sheet. */
436	@Service
437	public class StatementService {
438	
439	    /** A person's statements: how many have been taken, and the last one (null with none). */
440	    public record Summary(Long personId, int count, Statement last) {
441	    }
442	
443	    private final StatementRepository statements;
444	    private final PersonRepository people;
445	    private final ClaimRepository claims;
446	    private final ClaimService claimService;
447	    private final RateRepository rates;
448	    private final SheetService sheets;
449	    private final Audit audit;
450	
451	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
452	            ClaimService claimService, RateRepository rates, SheetService sheets, Audit audit) {
453	        this.statements = statements;
454	        this.people = people;
455	        this.claims = claims;
456	        this.claimService = claimService;
457	        this.rates = rates;
458	        this.sheets = sheets;
459	        this.audit = audit;
460	    }
461	
462	    /** Each person's statements on the sheet, for the people who have any. */
463	    @Transactional(readOnly = true)
464	    public List<Summary> list(String sheetId) {
465	        Map<Long, Summary> by = new LinkedHashMap<>();
466	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
467	            Summary was = by.get(s.getPersonId());
468	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
469	        }
470	        return List.copyOf(by.values());
471	    }
472	
473	    /**
474	     * Takes a statement for the person: records their due-total now and binds each of their claims that counts to
475	     * the figure it has now; a claim that does not count is freed (live again).
476	     */
477	    @Transactional
478	    public Summary take(String by, String sheetId, Long personId) {
479	        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
480	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
481	        LocalDate today = sheets.load(sheetId).getToday();
482	        BigDecimal total = BigDecimal.ZERO.setScale(2);
483	        boolean kept = false;
484	        int count = 0;
485	        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
486	            if (!c.getStatus().counts()) {
487	                c.unbind();
488	                continue;
489	            }
490	            // a settled or already bound claim keeps its figure even with no rate in force today
491	            kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
492	            BigDecimal figure = claimService.figure(sheetId, person, c);
493	            c.bind(figure);
494	            count++;
495	            if (figure != null) {
496	                total = total.add(figure);
497	            }
498	        }
499	        claims.flush();
500	        // as on screen: with no rate in force today for their grade and no kept figure, the due-total is n/a
501	        boolean current = rates.findInForce(sheetId, person.getGrade(), today).isPresent();
502	        BigDecimal dueTotal = current || kept ? total : null;
503	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today));
504	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
505	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
506	        return new Summary(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId).size(),
507	                taken);
508	    }
509	}
